}
''')
B=LoyaltyTier='LoyaltyTier'
def rows(rs): return '\n'.join('    [InlineData(%s)]'%r for r in rs)
def theory(name,title,sig,rs,body):
    return f'''
    // {title}
    [Theory]
{rows(rs)}
    public void {name}({sig})
    {{
{body}
    }}
'''
L='''        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(%s));

%s'''
def both(args): return L%(args,'        Assert.Equal(discount, quote.DiscountCents);\n        Assert.Equal(total, quote.TotalCents);')
t=[]
t.append(theory('S1_MemberReceivesTheDiscountOfTheirTier','Member receives the loyalty discount of their tier','LoyaltyTier tier, int discount, int total',
 ['LoyaltyTier.Bronze, 500, 9500','LoyaltyTier.Silver, 1000, 9000','LoyaltyTier.Gold, 1500, 8500'],both('10000, tier')))
t.append(theory('S2_LoyaltyDiscountNeverExceedsTwentyEuros','The loyalty discount never exceeds 20.00 EUR','int subtotal, LoyaltyTier tier, int discount, int total',
 ['20000, LoyaltyTier.Gold, 2000, 18000','30000, LoyaltyTier.Silver, 2000, 28000','12000, LoyaltyTier.Gold, 1800, 10200'],both('subtotal, tier')))
t.append(theory('S3_NoLoyaltyDiscountUnderThirtyEuros','No loyalty discount under a 30.00 EUR subtotal','int subtotal, int discount, int total',
 ['2999, 0, 2999','3000, 450, 2550'],both('subtotal, LoyaltyTier.Gold')))
t.append(theory('S4_WelcomeFiveTakesFiveEurosAfterLoyaltyDiscount','The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount','int subtotal, LoyaltyTier tier, int discount, int total',
 ['10000, LoyaltyTier.Silver, 1500, 8500','2000, LoyaltyTier.Bronze, 500, 1500'],both('subtotal, tier, "WELCOME5"')))
t.append(theory('S5_CapAppliesToLoyaltyDiscountOnly','The cap applies to the loyalty discount only, never to WELCOME5','int subtotal, LoyaltyTier tier, int discount, int total',
 ['20000, LoyaltyTier.Gold, 2500, 17500','30000, LoyaltyTier.Silver, 2500, 27500'],both('subtotal, tier, "WELCOME5"')))
t.append(theory('S6_PromoCodesIgnoreCase','Promo codes ignore case','string code',
 ['"welcome5"','"Welcome5"'],L%('10000, LoyaltyTier.Silver, code','        Assert.Equal(1500, quote.DiscountCents);')))
t.append(theory('S7_SummerTenTakesTenPercentCappedAtFifteenEuros','The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR','int subtotal, LoyaltyTier tier, int discount, int total',
 ['10000, LoyaltyTier.Silver, 1900, 8100','30000, LoyaltyTier.Bronze, 3000, 27000','2000, LoyaltyTier.Gold, 200, 1800'],both('subtotal, tier, "SUMMER10"')))
t.append('''
    // An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored()
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver, "SPRING"));

        Assert.Equal(1000, quote.DiscountCents);
        Assert.Equal(9000, quote.TotalCents);
    }
''')
t.append(theory('S9_PlatinumReceivesTwentyPercent','Platinum members receive a 20 % loyalty discount','int subtotal, int discount, int total',
 ['10000, 2000, 8000','5000, 1000, 4000','20000, 2000, 18000'],both('subtotal, LoyaltyTier.Platinum')))
t.append(theory('S10_DiscountNeverExceedsSubtotal','The discount never exceeds the subtotal','int subtotal, LoyaltyTier tier, int discount',
 ['400, LoyaltyTier.Bronze, 400','300, LoyaltyTier.Gold, 300'],L%('subtotal, tier, "WELCOME5"','        Assert.Equal(discount, quote.DiscountCents);\n        Assert.Equal(0, quote.TotalCents);')))
w(T+'LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs','''using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{'''+''.join(t)+'}\n')
S='''        var fee = new CalculateShippingFee().Handle(
            new CalculateShippingFeeQuery(%s));

        Assert.Equal(%s, fee);'''
w(T+'Shipping/CalculateShippingFeeAcceptanceTests.cs','''using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Shipping;

public sealed class CalculateShippingFeeAcceptanceTests
{'''+theory('S11_StandardShippingIsFreeFromFiftyEurosPayable','Standard shipping is free from 50.00 EUR payable','int total, LoyaltyTier tier, int fee',
 ['4999, LoyaltyTier.Bronze, 490','5000, LoyaltyTier.Bronze, 0','4999, LoyaltyTier.Silver, 490'],S%('total, tier','fee'))
+theory('S12_GoldAndPlatinumNeverPayStandardShipping','Gold and Platinum members never pay standard shipping','LoyaltyTier tier',
 ['LoyaltyTier.Gold','LoyaltyTier.Platinum'],S%('1000, tier','0'))
+theory('S13_ExpressShippingIsFreeForPlatinumOnly','Express shipping costs 9.90 EUR, free for Platinum members only','int total, LoyaltyTier tier, int fee',
 ['10000, LoyaltyTier.Bronze, 990','1000, LoyaltyTier.Gold, 990','1000, LoyaltyTier.Platinum, 0'],S%('total, tier, Express: true','fee'))+'}\n')
w(T+'CheckoutQuote/QuoteCheckoutAcceptanceTests.cs','''using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.CheckoutQuote;

public sealed class QuoteCheckoutAcceptanceTests
